                if (bounds.containsKey("exclusiveMinimum") && n <= num(bounds["exclusiveMinimum"]) || bounds.containsKey("exclusiveMaximum") && n >= num(bounds["exclusiveMaximum"])) throw refused("exclusive numeric bound")
                if (bounds.containsKey("multipleOf")) {
                    val divisor = num(bounds["multipleOf"])
                    if (divisor <= 0 || kotlin.math.abs(n / divisor - Math.rint(n / divisor)) > 1e-9) throw refused("multipleOf mismatch")
                }
            }
            if (value is String) range(value.codePointCount(0, value.length).toDouble(), bounds, "minLength", "maxLength")
            if (value is List<*>) {
                range(value.size.toDouble(), bounds, "minItems", "maxItems"); val unique = mutableSetOf<String>()
                for (item in value) {
                    if (flag(bounds, "uniqueItems") && !unique.add(String(bytes(item), Charsets.UTF_8))) throw refused("duplicate array item")
                    if (schema.containsKey("items")) validate(item, obj(schema["items"]), schemas, depth + 1)
                }
            }
            if (value is Map<*, *>) {
                val fields = obj(value); range(fields.size.toDouble(), bounds, "minProperties", "maxProperties")
                val properties = obj(schema["properties"] ?: emptyMap<String, Any?>())
                for (key in arr(schema["required"] ?: emptyList<String>())) if (!fields.containsKey(str(key))) throw refused("required property missing")
                for ((key, item) in fields) {
                    if (properties.containsKey(key)) validate(item, obj(properties[key]), schemas, depth + 1)
                    else if (schema["additional_properties"] == false) throw refused("unknown object property")
                    else if (schema["additional_properties"] is Map<*, *>) validate(item, obj(schema["additional_properties"]), schemas, depth + 1)
                }
            }
        }
    }

    /** Authenticated local storage; keep the checkpoint and permanent initialization guard together. */
    public class Checkpoint(path: java.nio.file.Path, key: ByteArray) {
        private val path = path.toAbsolutePath().normalize()
        private val key = key.copyOf()
        private var revision = ""
        init { if (key.size < 32) throw refused("external checkpoint key of at least 32 bytes required") }
        private fun sibling(suffix: String): java.nio.file.Path = path.resolveSibling(path.fileName.toString() + suffix)
        private fun mac(value: Any?): ByteArray = javax.crypto.Mac.getInstance("HmacSHA256").run {
            init(javax.crypto.spec.SecretKeySpec(key, "HmacSHA256")); doFinal(bytes(value))
        }
        private fun read(): ByteArray? = try {
            java.nio.channels.FileChannel.open(path, java.nio.file.StandardOpenOption.READ).use { channel ->
                val length = channel.size()
                if (length > 128L * 1024 * 1024) throw refused("checkpoint byte limit")
                val buffer = java.nio.ByteBuffer.allocate(length.toInt())
                while (buffer.hasRemaining()) if (channel.read(buffer) < 0) throw refused("checkpoint changed during read")
                if (channel.read(java.nio.ByteBuffer.allocate(1)) != -1) throw refused("checkpoint changed during read")
                buffer.array()
            }
        } catch (_: java.nio.file.NoSuchFileException) { null }
        @Synchronized internal fun load(): Map<String, Any?>? {
            try {
                val payload = read()
                if (payload == null) {
                    if (java.nio.file.Files.exists(sibling(".started"))) throw refused("checkpoint missing after initialization")
                    revision = ""; return null
                }
                if (!java.nio.file.Files.exists(sibling(".started"))) throw refused("checkpoint initialization guard missing")
                val envelope = obj(parse(payload))
                if (envelope.keys != setOf("state", "mac")) throw refused("invalid checkpoint envelope")
                val supplied = try { java.util.HexFormat.of().parseHex(str(envelope["mac"])) } catch (error: IllegalArgumentException) { throw refused("checkpoint authentication failed", error) }
                if (!java.security.MessageDigest.isEqual(supplied, mac(envelope["state"]))) throw refused("checkpoint authentication failed")
                revision = hash(payload); return obj(envelope["state"])
            } catch (error: SessionException) { throw error }
            catch (error: Exception) { throw refused("checkpoint load failed", error) }
        }
        @Synchronized internal fun save(state: Map<String, Any?>) {
            try {
                java.nio.file.Files.createDirectories(path.parent)
                val lock = sibling(".lock")
                val writer = java.nio.channels.FileChannel.open(lock, java.nio.file.StandardOpenOption.CREATE_NEW, java.nio.file.StandardOpenOption.WRITE)
                try {
                    writer.use {
                        var temporary: java.nio.file.Path? = null
                        try {
                            val previous = read()
                            if ((previous?.let { hash(it) } ?: "") != revision) throw refused("checkpoint changed by another session")
                            val payload = bytes(mapOf("state" to state, "mac" to hex(mac(state))))
                            if (payload.size > 128 * 1024 * 1024) throw refused("checkpoint byte limit")
                            if (revision.isEmpty()) {
                                java.nio.channels.FileChannel.open(sibling(".started"), java.nio.file.StandardOpenOption.CREATE_NEW, java.nio.file.StandardOpenOption.WRITE).use { guard ->
                                    val data = java.nio.ByteBuffer.wrap(PROTOCOL.toByteArray(Charsets.UTF_8))
                                    while (data.hasRemaining()) guard.write(data)
                                    guard.force(true)
                                }
                            } else if (!java.nio.file.Files.exists(sibling(".started"))) throw refused("checkpoint initialization guard missing")
                            val pending = sibling("." + java.util.UUID.randomUUID() + ".tmp"); temporary = pending
                            java.nio.channels.FileChannel.open(pending, java.nio.file.StandardOpenOption.CREATE_NEW, java.nio.file.StandardOpenOption.WRITE).use { file ->
                                val data = java.nio.ByteBuffer.wrap(payload)
                                while (data.hasRemaining()) file.write(data)
                                file.force(true)
                            }
                            java.nio.file.Files.move(pending, path, java.nio.file.StandardCopyOption.ATOMIC_MOVE, java.nio.file.StandardCopyOption.REPLACE_EXISTING)
                            temporary = null; revision = hash(payload)
                        } finally { temporary?.let { java.nio.file.Files.deleteIfExists(it) } }
                    }
                } finally { java.nio.file.Files.delete(lock) } // Only after this writer acquired the lock.
            } catch (error: java.io.IOException) { throw refused("checkpoint persistence failed", error) }
        }
    }

    private val registry = discovery()
    private val schemas = obj(parse(SCHEMAS_JSON.toByteArray(Charsets.UTF_8)))
    private val limits = options.limits.toMap()
    private val allowed = options.allowedTools.toSet()
    private val running = java.util.concurrent.atomic.AtomicBoolean()
    private var storageFailure: Throwable? = null
    private val state: MutableMap<String, Any?>

    init {
        if (limits.keys != KEYS.toSet() || limits.any { (key, value) -> !value.isFinite() || value <= 0 || count(key) && (Math.rint(value) != value || value > 9007199254740991.0) }) throw refused("all nine positive finite budgets and safe integer counts required")
        if (!digest(options.artifactHash) || provider.version != PROVIDER_PROTOCOL || provider.identity.isEmpty()) throw refused("provider identity and exact archive hash required")
        if (allowed.isEmpty() || allowed.size != options.allowedTools.size || !registry.keys.containsAll(allowed)) throw refused("explicit unique known operation allowlist required")
        val binding = mapOf("version" to PROTOCOL, "language" to "kotlin", "source" to SOURCE,
            "artifact" to options.artifactHash, "registry" to hash(REGISTRY_JSON.toByteArray(Charsets.UTF_8)),
            "provider" to mapOf("identity" to provider.identity, "version" to provider.version), "limits" to limits, "allowed_tools" to allowed.sorted())
        val initial = linkedMapOf<String, Any?>("binding" to binding, "used" to KEYS.associateWith { 0.0 }.toMutableMap(),
            "observed_usage" to mutableMapOf("tokens" to 0.0, "cost" to 0.0, "elapsed_seconds" to 0.0), "deadline" to 0.0,
            "receipts" to emptyList<Any?>(), "pending" to emptyList<Any?>(), "final" to false, "final_result" to null)
        state = (options.checkpoint.load() ?: initial).toMutableMap()
        if (state.keys != initial.keys || !equal(state["binding"], binding)) throw refused("stale or mixed checkpoint")
        val used = used()
        if (used.keys != limits.keys || used.any { (key, value) -> num(value) < 0 || num(value) > limits.getValue(key) || count(key) && Math.rint(num(value)) != num(value) }) throw refused("corrupt budget state")
        if (num(state["deadline"]) < 0 || state["final"] !is Boolean) throw refused("corrupt deadline or final state")
        val observed = obj(state["observed_usage"])
        if (observed.keys != setOf("tokens", "cost", "elapsed_seconds") || observed.values.any { num(it) < 0 }) throw refused("corrupt observed usage")
        val seen = mutableSetOf<String>(); var previous = "0".repeat(64)
        for (item in arr(state["receipts"])) {
            val receipt = obj(item); val actual = str(receipt["hash"])
            val unsigned = receipt.toMutableMap(); unsigned["hash"] = null
            if (receipt.keys != setOf("id", "tool", "arguments_hash", "mutation", "result", "previous", "hash") || receipt["previous"] != previous || hash(bytes(unsigned)) != actual) throw refused("corrupt receipt chain")
            checkCall(receipt, seen); previous = actual
        }
        for (item in arr(state["pending"])) {
            val pending = obj(item)
            if (pending.keys != setOf("id", "tool", "arguments_hash", "mutation")) throw refused("corrupt pending call")
            checkCall(pending, seen)
        }
        if (flag(state, "final") && arr(state["pending"]).isNotEmpty()) throw refused("corrupt final state")
    }
    private fun checkCall(call: Map<String, Any?>, seen: MutableSet<String>) {
        val id = str(call["id"]); val tool = str(call["tool"])
        if (id.isEmpty() || !seen.add(id) || tool !in allowed || !digest(str(call["arguments_hash"])) || call["mutation"] !is Boolean || flag(call, "mutation") != flag(obj(registry[tool]), "mutation")) throw refused("corrupt call state")
    }
    @Suppress("UNCHECKED_CAST") private fun mutable(value: Any?): MutableMap<String, Any?> = obj(value) as MutableMap<String, Any?>
    private fun used(): MutableMap<String, Any?> = mutable(state["used"])
    private fun begin() {
        if (!running.compareAndSet(false, true)) throw refused("session already running")
        if (storageFailure != null) { running.set(false); throw refused("checkpoint write failed; reload before continuing", storageFailure) }
    }
    private fun persist() {
        try { options.checkpoint.save(state) }
        catch (error: Exception) { storageFailure = error; throw error }
    }
    private fun charge(key: String, amount: Double) {
        val next = num(used()[key]) + amount
        if (!amount.isFinite() || amount < 0 || !next.isFinite() || next > limits.getValue(key)) throw refused("budget exceeded: " + key)
        used()[key] = next
    }
    private fun project(tool: String, value: Any?): Any? = clean(options.persistResult(tool, value)).also { charge("output_bytes", bytes(it).size.toDouble()) }
    private fun acknowledge(call: Map<String, Any?>, value: Any?) {
        val before = arr(state["receipts"]); val pending = arr(state["pending"])
        val receipt = call.toMutableMap(); receipt["result"] = project(str(call["tool"]), value)
        receipt["previous"] = if (before.isEmpty()) "0".repeat(64) else obj(before.last())["hash"]
        receipt["hash"] = null; receipt["hash"] = hash(bytes(receipt))
        state["receipts"] = before + receipt; state["pending"] = pending.filter { obj(it)["id"] != call["id"] }
        try { persist() } catch (error: Exception) { state["receipts"] = before; state["pending"] = pending; throw error }
    }
    /** Persist an externally verified outcome without invoking the SDK. */
    public fun reconcile(callId: String, knownResult: Any?) {
        begin()
        try {
            val call = arr(state["pending"]).map { obj(it) }.firstOrNull { it["id"] == callId } ?: throw refused("unknown in-doubt call")
            acknowledge(call, knownResult)
        } finally { running.set(false) }
    }
    private fun prepare(call: Call): suspend (RequestOptions) -> Any? {
        try {
            return when (call.tool) {
            "getHealth" -> {
                val params = GetHealthParams()
                val invocation: suspend (RequestOptions) -> Any? = { options -> nativeValue(client.getHealth(params, options).value) }
                invocation
            }
            "getSignupPolicy" -> {
                val params = GetSignupPolicyParams()
                val invocation: suspend (RequestOptions) -> Any? = { options -> nativeValue(client.getSignupPolicy(params, options).value) }
                invocation
            }
            "submitWaitlistRequest" -> {
                val params = SubmitWaitlistRequestParams()
                val invocation: suspend (RequestOptions) -> Any? = { options -> nativeValue(client.submitWaitlistRequest(params, options).value) }
                invocation
            }
            "loginUser" -> {
                val params = LoginUserParams()
                val invocation: suspend (RequestOptions) -> Any? = { options -> nativeValue(client.loginUser(params, options).value) }
                invocation
            }
            "getCurrentUser" -> {
                val params = GetCurrentUserParams()
                val invocation: suspend (RequestOptions) -> Any? = { options -> nativeValue(client.getCurrentUser(params, options).value) }
                invocation
            }
            "reserveUsageQuota" -> {
                val params = ReserveUsageQuotaParams()
                val invocation: suspend (RequestOptions) -> Any? = { options -> nativeValue(client.reserveUsageQuota(params, options).value) }
                invocation
            }
            "finalizeUsageQuota" -> {
                val params = FinalizeUsageQuotaParams()
                val invocation: suspend (RequestOptions) -> Any? = { options -> nativeValue(client.finalizeUsageQuota(params, options).value) }
                invocation
            }
            "failUsageQuota" -> {
                val params = FailUsageQuotaParams()
                val invocation: suspend (RequestOptions) -> Any? = { options -> nativeValue(client.failUsageQuota(params, options).value) }
                invocation
            }
                else -> throw refused("operation not qualified")
            }
        } catch (error: Exception) { throw refused("native SDK argument decoding failed", error) }
    }
    private fun remainingSeconds(): Double = minOf(limits.getValue("elapsed_seconds") - num(used()["elapsed_seconds"]), num(state["deadline"]) - now())
    private fun deadlineMillis(): Long {
        val seconds = remainingSeconds()
        if (seconds <= 0) throw kotlinx.coroutines.CancellationException("session deadline exceeded")
        return maxOf(1, minOf(Int.MAX_VALUE.toDouble(), seconds * 1000).toLong())
    }
    public suspend fun run(input: Any?): Any? {
        begin()
        try { return runStarted(input) } finally { running.set(false) }
    }
    private suspend fun runStarted(input: Any?): Any? {
        if (arr(state["pending"]).isNotEmpty()) throw SessionException("explicit reconciliation required; no call will be retried", inDoubt = true)
        if (flag(state, "final")) return clean(state["final_result"])
        val started = System.nanoTime()
        if (num(state["deadline"]) == 0.0) state["deadline"] = now() + limits.getValue("elapsed_seconds") - num(used()["elapsed_seconds"])
        var failure: Throwable? = null; var result: Any? = null
        try {
            val detachedInput = clean(input); charge("input_bytes", bytes(detachedInput).size.toDouble())
            while (true) {
                kotlinx.coroutines.currentCoroutineContext().ensureActive()
                deadlineMillis(); charge("turns", 1.0); charge("model_calls", 1.0); persist()
                val receipts = arr(state["receipts"]).map { item ->
                    val r = obj(clean(item)); Receipt(str(r["id"]), str(r["tool"]), str(r["arguments_hash"]), flag(r, "mutation"), r["result"], str(r["previous"]), str(r["hash"]))
                }
                val tools = allowed.associateWith { clean(registry[it]) }
                charge("input_bytes", bytes(mapOf("protocol" to PROTOCOL, "input" to detachedInput, "results" to state["receipts"], "tools" to tools)).size.toDouble())
                val context = Context(PROTOCOL, clean(detachedInput), receipts, tools)
                val remaining = limits.mapValues { (key, value) -> value - num(used()[key]) }
                val proposal = kotlinx.coroutines.withTimeout(deadlineMillis()) { provider.propose(context, remaining) }
                if (proposal.completed && proposal.calls != null || !proposal.completed && proposal.result != null) throw refused("proposal must contain calls or final exclusively")
                charge("input_bytes", bytes(mapOf("usage" to mapOf("tokens" to proposal.usage.tokens, "cost" to proposal.usage.cost), "calls" to proposal.calls?.map { mapOf("id" to it.id, "tool" to it.tool, "arguments" to it.arguments) }, "completed" to proposal.completed, "result" to proposal.result)).size.toDouble())
                for ((key, amount) in mapOf("tokens" to proposal.usage.tokens, "cost" to proposal.usage.cost)) {
                    if (!amount.isFinite() || amount < 0 || key == "tokens" && (Math.rint(amount) != amount || amount > 9007199254740991.0)) throw refused("invalid provider usage")
                    val observed = mutable(state["observed_usage"]); val total = num(observed[key]) + amount
                    if (!total.isFinite()) throw refused("provider usage overflow")
                    observed[key] = total
                }
                charge("tokens", proposal.usage.tokens); charge("cost", proposal.usage.cost)
                if (proposal.completed) {
                    result = project("\$final", proposal.result); state["final_result"] = result; state["final"] = true; persist(); break
                }
                val calls = proposal.calls ?: throw refused("calls required")
                if (calls.isEmpty() || calls.size > limits.getValue("concurrency")) throw refused("empty batch or concurrency budget exceeded")
                val seen = arr(state["receipts"]).map { str(obj(it)["id"]) }.toMutableSet()
                val pending = mutableListOf<Map<String, Any?>>()
                val invocations = mutableListOf<suspend (RequestOptions) -> Any?>()
                for (proposed in calls) {
                    if (proposed.id.isEmpty() || !seen.add(proposed.id) || proposed.tool !in allowed) throw refused("unknown tool or duplicate ID")
                    val call = proposed.copy(arguments = obj(clean(proposed.arguments)))
                    val descriptor = obj(registry[call.tool])
                    if (descriptor["execution"] != "buffered-json") throw refused("stream/upload operation is not qualified")
                    val fields = mutableSetOf<String>()
                    for (field in arr(descriptor["arguments"])) {
                        val argument = obj(field); val name = str(argument["name"]); fields.add(name)
                        val exists = call.arguments.containsKey(name)
                        if (!exists && flag(argument, "required")) throw refused("required argument missing")
                        if (!exists) continue
                        if (flag(argument, "caller_only")) throw refused("header/cookie arguments require caller configuration")
                        validate(call.arguments[name], obj(argument["schema"]), schemas)
                    }
                    if (!fields.containsAll(call.arguments.keys)) throw refused("unknown argument; request options forbidden")
                    invocations.add(prepare(call)); pending.add(mapOf("id" to call.id, "tool" to call.tool, "arguments_hash" to hash(bytes(call.arguments)), "mutation" to flag(descriptor, "mutation")))
                }
                charge("tool_calls", pending.size.toDouble())
                for (call in pending) if (flag(call, "mutation") && !kotlinx.coroutines.withTimeout(deadlineMillis()) { options.approveWrite(str(call["tool"]), str(call["arguments_hash"])) }) throw refused("explicit write approval required")
                kotlinx.coroutines.currentCoroutineContext().ensureActive(); val timeout = deadlineMillis()
                val bound = minOf(67108864.0, limits.getValue("output_bytes") - num(used()["output_bytes"])).toInt()
                if (bound < 1) throw refused("output budget exceeded")
                state["pending"] = pending; persist()
                val requestOptions = RequestOptions(agentSessionMaxResponseBytes = bound, agentSessionTimeout = java.time.Duration.ofMillis(timeout))
                val values = kotlinx.coroutines.withTimeout(timeout) {
                    kotlinx.coroutines.coroutineScope {
                        invocations.map { invocation -> async(kotlinx.coroutines.Dispatchers.IO) { invocation(requestOptions) } }.awaitAll()
                    }
                }
                for (index in values.indices) acknowledge(pending[index], values[index])
            }
        } catch (error: Throwable) { failure = error }
        finally {
            val elapsed = num(used()["elapsed_seconds"]) + (System.nanoTime() - started) / 1e9
            mutable(state["observed_usage"])["elapsed_seconds"] = elapsed
            used()["elapsed_seconds"] = minOf(limits.getValue("elapsed_seconds"), elapsed)
            try { persist() } catch (storage: Throwable) { failure?.let { storage.addSuppressed(it) }; failure = storage }
            try {
                kotlinx.coroutines.withContext(kotlinx.coroutines.NonCancellable) {
                    kotlinx.coroutines.withTimeout(maxOf(1, minOf(1000.0, limits.getValue("elapsed_seconds") * 1000).toLong())) { provider.close() }
                }
            } catch (closeError: Throwable) {
                val wrapped = refused("provider cleanup failed; callbacks remain caller-owned", closeError)
                failure?.let { wrapped.addSuppressed(it) }; failure = wrapped
            }
        }
        failure?.let { error ->
            if (arr(state["pending"]).any { flag(obj(it), "mutation") }) throw SessionException("explicit reconciliation required; no call will be retried", error, true)
            throw error
        }
        return result
    }
}
